mapper.select:
SELECT id, name, is_template, create_time, expires_at
FROM shops
WHERE id = #{id}

mapper.insert:
INSERT INTO admin (id, username, password, name, phone, role, shop_id, status, create_time, update_time)
SELECT id + #{offset}, CONCAT(username, '_', #{shopId}), MD5(RAND()), name, phone, role, #{shopId}, status, #{now}, #{now}
FROM admin WHERE shop_id = 1

INSERT INTO after_sale_only_refunds (id, after_sale_id, review_at, rejected_at, refund_at, refunded_at, created_at, updated_at, is_deleted, shop_id)
SELECT id + #{offset}, after_sale_id + #{offset}, review_at, rejected_at, refund_at, refunded_at, created_at, updated_at, is_deleted, #{shopId}
FROM after_sale_only_refunds WHERE shop_id = 1
